/// Filter Operator
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum FilterOperatorValues {
    Equal,
    LessThan,
    LessThanOrEqual,
    NotEqual,
    GreaterThanOrEqual,
    GreaterThan,
}

impl FilterOperatorValues {
    /// Schema string value.
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Equal => "equal",
            Self::LessThan => "lessThan",
            Self::LessThanOrEqual => "lessThanOrEqual",
            Self::NotEqual => "notEqual",
            Self::GreaterThanOrEqual => "greaterThanOrEqual",
            Self::GreaterThan => "greaterThan",
        }
    }

    /// Parse from the schema string value.
    pub fn from_str(s: &str) -> Option<Self> {
        match s {
            "equal" => Some(Self::Equal),
            "lessThan" => Some(Self::LessThan),
            "lessThanOrEqual" => Some(Self::LessThanOrEqual),
            "notEqual" => Some(Self::NotEqual),
            "greaterThanOrEqual" => Some(Self::GreaterThanOrEqual),
            "greaterThan" => Some(Self::GreaterThan),
            _ => None,
        }
    }
}

impl core::fmt::Display for FilterOperatorValues {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        f.write_str(self.as_str())
    }
}

impl crate::simple_types::OpenXmlSimpleType for FilterOperatorValues {
    fn as_inner_text(&self) -> String {
        self.as_str().to_string()
    }
    fn from_inner_text(text: &str) -> Option<Self> {
        Self::from_str(text)
    }
}

